def f(grid):
    n=len(grid); g=[row[:] for row in grid]
    def img(t):
        r,c=t; m=n+1
        return [(r,c),(c,r),(m-1-r,c),(r,m-1-c),(m-1-r,m-1-c),(m-1-c,r),(c,m-1-r),(m-1-c,m-1-r)]
    six=[(r,c) for r in range(n) for c in range(n) if grid[r][c]==6]
    for r,c in six:
        for a,b in img((r,c)):
            if 0<=a<n and 0<=b<n and grid[a][b]!=6:
                g[r][c]=grid[a][b]; break
        else:
            g[r][c]=6
    return g
